content.content:
1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	/* page-portfolio（404）・page-privacy はTOPページと同じネイビー×オレンジ配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
12	body.page-portfolio { background: #FFFFFF; color: #172E4A; }
13	body.page-privacy { background: #FFFFFF; color: #172E4A; }
14	body.page-pianist { background: #08080A; color: #F2EFE9; }
15	body:has(.pn-shell) {
16	  color: #F2EFE9;
17	  background: linear-gradient(180deg,rgba(8,8,10,0.4),rgba(8,8,10,0.65)), url("images/25253200_l.webp") center / cover no-repeat fixed, #08080A;
18	}
19	body:has(.top-shell) {
20	  background: #FFFFFF;
21	}
22	body.page-portfolio a:hover { color: #DC8541; }
23	body.page-privacy a:hover { color: #DC8541; }
24	body.page-pianist a:hover { color: #E4C97E; }
25	.pn-shell a:hover { color: #E4C97E; }
26	body.page-portfolio ::selection,
27	body.page-privacy ::selection { background: #F6D3B0; color: #172E4A; }
28	
29	body.page-horror { background: #07070A; color: #D6D2CB; }
30	body.page-horror a:hover { color: #9B2C22; }
31	
32	/* ============================================
33	   キーフレームアニメーション
34	   ============================================ */
35	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
36	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
37	
38	/* ============================================
39	   共通ユーティリティ
40	   ============================================ */
41	.container { max-width: 1180px; margin: 0 auto; padding-inline: clamp(20px,5vw,64px); }
42	
43	.tag-row { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
44	.tag { display: inline-flex; align-items: center; font-size: 12px; letter-spacing: 0.01em; color: #3E4A5C; border: 1px solid #D8DCE3; border-radius: 999px; padding: 7px 15px; background: #FFFFFF; white-space: nowrap; }
45	.tag--onDark { color: #EAF0F6; border-color: rgba(234,240,246,0.32); background: rgba(255,255,255,0.06); }
46	
47	.btn-group { display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }
48	.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.1em; padding: 16px 30px; border-radius: 999px; border: 1.5px solid transparent; cursor: pointer; transition: background .25s ease, border-color .25s ease, color .25s ease, transform .15s ease; white-space: nowrap; }
49	.btn:hover { transform: translateY(-1px); }
50	.btn--primary { background: #DC8541; color: #FFFFFF; font-weight: 600; }
51	.btn--primary:hover { background: #C06E2E; }
52	.btn--secondary { background: transparent; color: #172E4A; border-color: #172E4A; }
53	.btn--secondary:hover { background: #172E4A; color: #FFFFFF; }
54	.btn--onDark { background: transparent; color: #FFFFFF; border-color: rgba(255,255,255,0.5); }
55	.btn--onDark:hover { background: rgba(255,255,255,0.12); border-color: #FFFFFF; }
56	.btn--sm { padding: 11px 20px; font-size: 12px; }
57	
58	/* ============================================
59	   shell（各ページ共通の外枠カード／pianist・horror・privacyと共有のため触らない）
60	   ============================================ */
61	.shell {
62	  container-type: inline-size;
63	  max-width: 375px;
64	  margin: 0 auto;
65	  min-height: 100svh;
66	  position: relative;
67	  overflow-x: hidden;
68	  display: flex;
69	  flex-direction: column;
70	  background: #F5F8FC;
71	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
72	}
73	.shell--muted { background: #F0F5FA; }
74	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
75	
76	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
77	.skip-link:focus { left: 12px; top: 12px; }
78	
79	/* ============================================
80	   page-header（下層ページの戻るリンクヘッダー／pianist・horror・privacyと共有のため触らない）
81	   ============================================ */
82	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
83	.page-header--dark { color: #8A8580; }
84	.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
85	.page-header__back:hover { gap: 18px; }
86	.page-header__label { color: #7B8DA6; }
87	
88	/* ============================================
89	   page-footer（下層ページ共通フッター／pianist・horror・privacyと共有のため触らない）
90	   ============================================ */
91	.page-footer { padding: clamp(40px,5cqw,72px) clamp(20px,6cqw,80px); border-top: 1px solid #D3DEEB; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; margin-top: auto; }
92	.page-footer--dark { border-top-color: #1E1D1D; color: #5A5652; }
93	
94	/* privacy は新デザイン（ネイビー×オレンジ）に上書き（pianist・horrorの共有.shell/.page-header/.page-footerには影響させない） */
95	body.page-privacy .shell {
96	  background: #FFFFFF;
97	  box-shadow: 0 0 90px rgba(23,46,74,0.10);
98	}
99	body.page-privacy .page-header,
100	body.page-privacy .page-footer {
101	  font-family: Jost, sans-serif;
102	}
103	body.page-privacy .page-header__label,
104	body.page-privacy .page-footer {
105	  color: #7C8798;
106	}
107	body.page-privacy .page-footer {
108	  border-top-color: #E3E6EB;
109	}
110	
111	/* ============================================
112	   top-shell（TOPページのラッパー／固定フレームは使わずフル幅レスポンシブ）
113	   ============================================ */
114	.top-shell {
115	  min-height: 100svh;
116	  display: flex;
117	  flex-direction: column;
118	}
119	
120	/* ============================================
121	   site-header（TOPページ固定ヘッダー／DCコンポーネントの状態クラス hero-nav / menu は名称を維持）
122	   ============================================ */
123	.hero-nav {
124	  position: sticky; top: 0; z-index: 96;
125	  display: flex; align-items: center; justify-content: space-between;
126	  gap: 20px;
127	  padding: 18px clamp(20px,5vw,64px);
128	  background: rgba(255,255,255,0.96);
129	  border-bottom: 1px solid #E3E6EB;
130	  backdrop-filter: blur(6px);
131	  -webkit-backdrop-filter: blur(6px);
132	}
133	.hero-nav__h1 { margin: 0; }
134	.hero-nav__logo { display: inline-flex; flex-direction: column; gap: 2px; line-height: 1; }
135	.hero-nav__logo-main { font-family: Jost, sans-serif; font-size: 17px; letter-spacing: 0.08em; color: #172E4A; font-weight: 500; }
136	.hero-nav__logo-sub { font-family: Jost, sans-serif; font-size: 9px; letter-spacing: 0.24em; color: #DC8541; }
137	
138	.hero-nav__nav { display: none; }
139	.hero-nav__nav-list { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: clamp(18px,2.4vw,34px); font-size: 14px; color: #3E4A5C; }
140	.hero-nav__nav-list a { transition: color .2s ease; }
141	.hero-nav__nav-list a:hover { color: #DC8541; }
142	.hero-nav__actions { display: flex; align-items: center; gap: 22px; }
143	
144	.hero-nav__toggle {
145	  width: 40px; height: 40px; display: flex; flex-direction: column;
146	  justify-content: center; align-items: center; gap: 6px; background: none; border: none;
147	  cursor: pointer; padding: 0; flex: none;
148	}
149	.hero-nav__bar {
150	  display: block; height: 2px; width: 22px; border-radius: 2px; background: #172E4A;
151	  transition: transform .35s cubic-bezier(.2,.7,.2,1), opacity .2s ease;
152	}
153	.hero-nav.is-open .hero-nav__bar--top { transform: translateY(4px) rotate(45deg); }
154	.hero-nav.is-open .hero-nav__bar--bottom { transform: translateY(-4px) rotate(-45deg); }
155	
156	@media (min-width: 880px) {
157	  .hero-nav__nav { display: block; }
158	  .hero-nav__toggle { display: none; }
159	}
160	@media (max-width: 879px) {
161	  .hero-nav__actions .btn { display: none; }
162	}
163	
164	/* ============================================
165	   menu（ハンバーガーで開くフルスクリーンナビ／DCコンポーネントの状態クラス menu は名称を維持）
166	   ============================================ */
167	.menu {
168	  position: fixed; inset: 0; z-index: 95;
169	  background: #172E4A;
170	  display: flex; flex-direction: column;
171	  overflow-y: auto; -webkit-overflow-scrolling: touch;
172	  padding: 96px clamp(24px,7vw,64px) 48px;
173	  transition: opacity .4s ease, visibility .4s ease;
174	  opacity: 0; visibility: hidden; pointer-events: none;
175	}
176	.menu.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
177	.menu__cta { margin-bottom: clamp(32px,6vw,56px); }
178	.menu__inner { display: grid; gap: clamp(30px,6vw,56px); width: 100%; max-width: 420px; }
179	.menu__group-title { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #7FA0C4; margin: 0 0 18px; }
180	.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-family: Jost, sans-serif; font-size: 19px; letter-spacing: 0.04em; color: #FFFFFF; }
181	.menu__social-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; font-size: 14px; color: #FFFFFF; }
182	.menu__social-link { display: inline-flex; align-items: center; gap: 12px; transition: transform .3s ease; }
183	.menu__social-link:hover { transform: translateX(8px); color: #DC8541; }
184	.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }
185	.menu__personal-link { display: block; }
186	.menu__personal-link-title { display: block; font-size: 15px; color: #FFFFFF; transition: transform .3s ease; }
187	.menu__personal-link:hover .menu__personal-link-title { transform: translateX(8px); color: #DC8541; }
188	.menu__personal-link-desc { display: block; font-size: 12px; color: #7FA0C4; margin-top: 4px; }
189	.menu__credit { margin: 36px 0 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #4C6689; }
190	
191	@media (min-width: 880px) {
192	  .menu { display: none; }
193	}
194	
195	/* ============================================
196	   section 基本パターン
197	   ============================================ */
198	.section { position: relative; padding-block: clamp(64px,9vw,120px); background: #FFFFFF; }
199	.section--alt { background: #F6F7F9; }
200	.section--dark { background: #172E4A; color: #EAF0F6; }
201	.section--tight { padding-block: clamp(40px,6vw,80px); }
202	
203	.section__head { max-width: 640px; margin-bottom: clamp(32px,5vw,64px); }
204	.section__head--center { margin-inline: auto; text-align: center; }
205	.section__eyebrow { display: block; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; text-transform: uppercase; color: #DC8541; margin: 0 0 14px; }
206	.section__heading { margin: 0; font-weight: 500; font-size: clamp(24px,3.2vw,38px); line-height: 1.5; letter-spacing: -0.01em; color: #172E4A; }
207	.section--dark .section__heading { color: #FFFFFF; }
208	.section__lead { margin: 18px 0 0; font-size: 15px; line-height: 1.95; color: #56637A; }
209	.section--dark .section__lead { color: #C3D0E0; }
210	
211	/* ============================================
212	   hero
213	   ============================================ */
214	.hero { padding-top: clamp(56px,9vw,96px); padding-bottom: clamp(56px,9vw,96px); background: #FFFFFF; overflow: hidden; }
215	.hero__inner { display: grid; gap: clamp(40px,6vw,64px); align-items: center; }
216	.hero__eyebrow { display: flex; align-items: center; gap: 14px; font-family: Jost, sans-serif; font-size: 12px; letter-spacing: 0.22em; color: #56637A; margin: 0 0 clamp(20px,3vw,28px); }
217	.hero__eyebrow-line { width: 32px; height: 1px; background: #D8DCE3; }
218	.hero__heading { margin: 0; font-weight: 500; font-size: clamp(30px,5.2vw,52px); line-height: 1.4; letter-spacing: -0.01em; color: #172E4A; }
219	.hero__line { display: block; }
220	.hero__highlight { color: #DC8541; }
221	.hero__lead { margin: clamp(22px,3vw,32px) 0 0; font-size: 15px; line-height: 2; color: #56637A; max-width: 46ch; }
222	.hero__tags { margin-top: clamp(22px,3vw,32px); }
223	.hero__actions { margin-top: clamp(28px,4vw,40px); }
224	
225	.hero__visual { position: relative; }
226	.hero__photo {
227	  width: 100%; max-width: 360px; margin: 0 auto; aspect-ratio: 4/5;
228	  border: 1px solid #D8DCE3; border-radius: 12px;
229	  background-image: repeating-linear-gradient(135deg,#F1F3F6 0 10px,#F8F9FA 10px 20px);
230	  display: flex; align-items: center; justify-content: center;
231	}
232	.hero__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #8A93A3; background: #FFFFFF; padding: 6px 14px; border: 1px solid #E3E6EB; border-radius: 999px; }
233	
234	@media (min-width: 860px) {
235	  .hero__inner { grid-template-columns: minmax(0,1fr) 320px; }
236	  .hero__visual { order: 2; }
237	}
238	
239	/* ============================================
240	   tile-grid（PROBLEMS / TEAM / WORK STYLE 共通）
241	   ============================================ */
242	.tile-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 14px; }
243	.tile { display: flex; flex-direction: column; align-items: center; gap: 14px; text-align: center; background: #FFFFFF; border: 1px solid #E3E6EB; border-radius: 10px; padding: clamp(22px,3vw,30px) 16px; }
244	.section--alt .tile { background: #FFFFFF; }
245	.tile__icon { display: flex; align-items: center; justify-content: center; width: 48px; height: 48px; border-radius: 50%; background: #F6F7F9; }
246	.tile__icon img { width: 24px; height: 24px; }
247	.tile__text { margin: 0; font-size: 14px; line-height: 1.75; color: #172E4A; font-weight: 500; }
248	.tile__label { font-size: 13px; font-weight: 500; color: #172E4A; }
249	
250	@media (min-width: 640px) {
251	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
252	}
253	@media (min-width: 880px) {
254	  .tile-grid--6 { grid-template-columns: repeat(6,1fr); }
255	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
256	}
257	
258	/* ============================================
259	   timeline（SCOPE / PROFILE経歴 共通）
260	   ============================================ */
261	.timeline { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
262	.timeline__item { display: flex; align-items: center; gap: 16px; padding: 18px 2px; border-bottom: 1px solid #E3E6EB; }
263	.timeline__item:first-child { padding-top: 0; }
264	.timeline__marker { flex: none; width: 38px; height: 38px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
265	.timeline__marker img { width: 18px; height: 18px; }
266	.timeline__marker { border: 1.5px solid #C7CEDA; background: #FFFFFF; }
267	.timeline__item--covered .timeline__marker { border-color: #172E4A; background: #172E4A; }
268	.timeline__item--covered .timeline__marker img { filter: brightness(0) invert(1); }
269	.timeline__body { flex: 1; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; }
270	.timeline__no { font-family: Jost, sans-serif; font-size: 11px; color: #A7AFBC; min-width: 20px; }
271	.timeline__label { font-size: 15px; font-weight: 500; color: #172E4A; }
272	.timeline__badge { font-size: 11px; letter-spacing: 0.04em; color: #A7AFBC; }
273	.timeline__item--covered .timeline__badge { color: #DC8541; font-weight: 600; }
274	
275	@media (min-width: 900px) {
276	  .timeline--scope { flex-direction: row; flex-wrap: wrap; position: relative; padding-top: 24px; }
277	  .timeline--scope::before { content: ""; position: absolute; top: 43px; left: 0; right: 0; height: 1px; background: #E3E6EB; }
278	  .timeline--scope .timeline__item { flex: 1 1 0; min-width: 96px; flex-direction: column; align-items: center; text-align: center; gap: 10px; border-bottom: none; padding: 0 4px; position: relative; }
279	  .timeline--scope .timeline__marker { position: relative; z-index: 1; }
280	  .timeline--scope .timeline__body { flex-direction: column; align-items: center; gap: 4px; }
281	}
282	
283	/* ============================================
284	   philosophy（PHILOSOPHY）
285	   ============================================ */
286	.chain { display: flex; flex-direction: column; align-items: stretch; gap: 4px; max-width: 900px; margin: 0 auto; }
287	.chain__node { background: #FFFFFF; color: #172E4A; border-radius: 10px; padding: clamp(22px,3vw,30px) clamp(20px,3vw,28px); text-align: center; flex: 1; }
288	.chain__node--accent { box-shadow: inset 0 3px 0 #DC8541; }
289	.chain__role { margin: 0; font-family: Jost, sans-serif; font-weight: 600; font-size: 13px; letter-spacing: 0.08em; color: #172E4A; }
290	.chain__points { list-style: none; margin: 16px 0 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
291	.chain__points .tag { font-size: 11px; padding: 6px 12px; }
292	.chain__arrow { align-self: center; color: #DC8541; font-size: 18px; line-height: 1; padding: 6px 0; transform: rotate(90deg); }
293	
294	.philosophy__points { list-style: none; margin: 20px 0 0; padding: 0; display: grid; gap: 10px; max-width: 40ch; }
295	.philosophy__points li { font-size: 14px; color: #FFFFFF; padding-left: 20px; position: relative; }
296	.philosophy__points li::before { content: "―"; position: absolute; left: 0; color: #DC8541; }
297	
298	@media (min-width: 820px) {
299	  .chain { flex-direction: row; align-items: stretch; }
300	  .chain__arrow { transform: none; }
301	}
302	
303	/* ============================================
304	   work-card（WORKS）
305	   ============================================ */
306	.work-grid { display: grid; grid-template-columns: 1fr; gap: 28px; }
307	.work-card { display: flex; flex-direction: column; background: #FFFFFF; border: 1px solid #E3E6EB; border-radius: 10px; overflow: hidden; }
308	.work-card__media { aspect-ratio: 4/3; background: #F6F7F9; overflow: hidden; }
309	.work-card__media img { display: block; width: 100%; height: 100%; object-fit: cover; }
310	.work-card__media--placeholder { display: flex; align-items: center; justify-content: center; background-image: repeating-linear-gradient(135deg,#F1F3F6 0 10px,#F8F9FA 10px 20px); }
311	.work-card__media--placeholder span { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 6px 12px; border: 1px solid #E3E6EB; border-radius: 999px; }
312	.work-card__body { padding: 24px clamp(20px,3vw,28px) clamp(24px,3vw,28px); display: flex; flex-direction: column; gap: 18px; }
313	.work-card__no { margin: 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
314	.work-card__title { margin: 8px 0 0; font-weight: 500; font-size: 19px; color: #172E4A; }
315	.work-card__field-label { margin: 0 0 8px; font-family: Jost, sans-serif; font-size: 10px; letter-spacing: 0.18em; color: #A7AFBC; text-transform: uppercase; }
316	.work-card__roles { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
317	.work-card__role { font-size: 12px; color: #3E4A5C; border: 1px solid #D8DCE3; border-radius: 999px; padding: 5px 12px; white-space: nowrap; }
318	.work-card__text { margin: 0; font-size: 13px; line-height: 1.9; color: #56637A; }
319	.work-card__result { margin: 0; padding-left: 14px; border-left: 3px solid #DC8541; font-size: 13px; font-weight: 700; color: #172E4A; line-height: 1.7; }
320	
321	@media (min-width: 720px) {
322	  .work-grid { grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); }
323	}
324	
325	/* ============================================
326	   process-row（DIRECTION SAMPLE）
327	   ============================================ */
328	.process-row { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; align-items: flex-start; gap: 4px 0; }
329	.process-row__item { display: flex; flex-direction: column; align-items: center; gap: 8px; width: 96px; }
330	.process-row__icon { display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: 50%; background: #F6F7F9; border: 1px solid #E3E6EB; }
331	.process-row__icon img { width: 22px; height: 22px; }
332	.process-row__label { font-size: 12px; line-height: 1.6; color: #3E4A5C; text-align: center; }
