467	.dream-stage__sky { position: absolute; inset: 0; opacity: .35; background: repeating-linear-gradient(90deg,transparent 0 46px,rgba(155,44,34,.12) 47px,transparent 48px); animation: dreamDrift 8s linear infinite; }
468	.dream-stage__ear { position: relative; width: 118px; height: 174px; border: 3px solid #B9B0A9; border-radius: 54% 46% 48% 52% / 44% 46% 54% 56%; transform: rotate(-17deg); opacity: .85; box-shadow: inset -10px -5px 0 rgba(155,44,34,.12); }
469	.dream-stage__ear::before { content: ""; position: absolute; width: 48px; height: 82px; left: 31px; top: 42px; border: 3px solid #8A8580; border-radius: 50%; }
470	.dream-stage__ear-hole { position: absolute; left: 49px; top: 78px; width: 23px; height: 34px; border: 4px solid #9B2C22; border-radius: 50%; background: #050506; }
