472	.dream-stage__insects { position: absolute; inset: 24px; color: #B9B0A9; opacity: 0; font: 24px/1 ui-monospace, monospace; }
473	.dream-stage__insects i { position: absolute; font-style: normal; }
474	.dream-stage__insects i:nth-child(1) { left: 14%; top: 18%; }.dream-stage__insects i:nth-child(2) { left: 76%; top: 20%; }.dream-stage__insects i:nth-child(3) { left: 21%; top: 70%; }.dream-stage__insects i:nth-child(4) { left: 68%; top: 74%; }.dream-stage__insects i:nth-child(5) { left: 44%; top: 10%; }.dream-stage__insects i:nth-child(6) { left: 85%; top: 51%; }.dream-stage__insects i:nth-child(7) { left: 6%; top: 48%; }.dream-stage__insects i:nth-child(8) { left: 48%; top: 86%; }
475	.dream-stage--still .dream-stage__ear { opacity: .08; transform: rotate(-17deg) scale(.82); }
