/* ============================================
   top-shell（TOPページのラッパー／固定フレームは使わずフル幅レスポンシブ／
   「手描きポップ」デザイン：太め枠線・オフセット影・回転バッジが基調）
   ============================================ */
.top-shell {
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
}
body:has(.top-shell) a:hover { color: #DC8541; }
body:has(.top-shell) ::selection { background: #F6D3B0; color: #172E4A; }

@keyframes prupru {
  0% { transform: rotate(-2deg) translate(0,0); }
  12% { transform: rotate(2.4deg) translate(2px,-1px); }
  26% { transform: rotate(-3.2deg) translate(-2px,1px); }
  40% { transform: rotate(2.6deg) translate(2px,1px); }
  54% { transform: rotate(-2.4deg) translate(-1px,-1px); }
  68% { transform: rotate(1.6deg) translate(1px,0); }
  84% { transform: rotate(-2.4deg) translate(-1px,0); }
  100% { transform: rotate(-2deg) translate(0,0); }
}

/* ============================================
   site-header（TOPページ固定ヘッダー／DCコンポーネントの状態クラス hero-nav / menu は名称を維持）
   ============================================ */
.hero-nav {
  position: sticky; top: 0; z-index: 96;
  display: flex; align-items: center; justify-content: space-between;
  gap: 20px;
  padding: 16px clamp(18px,5vw,56px);
  background: rgba(255,255,255,0.93);
  border-bottom: 4px solid #172E4A;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.hero-nav__h1 { margin: 0; }
.hero-nav__logo { display: inline-flex; align-items: baseline; gap: 12px; line-height: 1; }
.hero-nav__logo-main { font-size: 18px; letter-spacing: 0.09em; color: #172E4A; font-weight: 500; }
.hero-nav__logo-sub { font-size: 9px; letter-spacing: 0.26em; color: #DC8541; }

.hero-nav__nav { display: none; }
.hero-nav__nav-list { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: clamp(14px,1.8vw,28px); font-size: 13.5px; color: #3E4A5C; }
.hero-nav__nav-list a { transition: color .2s ease; }
.hero-nav__nav-list a:hover { color: #DC8541; }
.hero-nav__actions { display: flex; align-items: center; gap: 16px; }

.hero-nav__toggle {
  width: 44px; height: 44px; display: flex; flex-direction: column;
  justify-content: center; align-items: center; gap: 6px; background: none; border: none;
  cursor: pointer; padding: 0; flex: none;
}
.hero-nav__bar {
  display: block; height: 2px; width: 22px; border-radius: 2px; background: #172E4A;
  transition: transform .35s cubic-bezier(.2,.7,.2,1), opacity .2s ease;
}
.hero-nav.is-open .hero-nav__bar--top { transform: translateY(4px) rotate(45deg); }
.hero-nav.is-open .hero-nav__bar--bottom { transform: translateY(-4px) rotate(-45deg); }

@media (min-width: 880px) {
  .hero-nav__nav { display: block; }
  .hero-nav__toggle { display: none; }
}
@media (max-width: 879px) {
  .hero-nav__actions .btn { display: none; }
}

/* ============================================
   menu（ハンバーガーで開くフルスクリーンナビ／DCコンポーネントの状態クラス menu は名称を維持）
   ============================================ */
.menu {
  position: fixed; inset: 0; z-index: 95;
  background: #172E4A;
  display: flex; flex-direction: column;
  overflow-y: auto; -webkit-overflow-scrolling: touch;
  padding: 96px clamp(24px,7vw,56px) 48px;
  transition: opacity .4s ease, visibility .4s ease;
  opacity: 0; visibility: hidden; pointer-events: none;
}
.menu.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
.menu__cta { margin-bottom: clamp(30px,6vw,48px); }
.menu__inner { display: grid; gap: clamp(28px,6vw,44px); width: 100%; max-width: 420px; }
.menu__group-title { font-size: 11px; letter-spacing: 0.24em; color: #9DB4CD; margin: 0 0 16px; }
.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-weight: 700; font-size: 20px; line-height: 1.25; color: #FFFFFF; }
.menu__social-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; font-size: 14px; color: #FFFFFF; }
.menu__social-link { display: inline-flex; align-items: center; gap: 12px; transition: transform .3s ease; }
.menu__social-link:hover { transform: translateX(8px); color: #DC8541; }
.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }
.menu__personal-link { display: block; }
.menu__personal-link-title { display: block; font-size: 15px; color: #FFFFFF; transition: transform .3s ease; }
.menu__personal-link:hover .menu__personal-link-title { transform: translateX(8px); color: #DC8541; }
.menu__personal-link-desc { display: block; font-size: 12px; color: #9DB4CD; margin-top: 4px; }
.menu__credit { margin: 36px 0 0; font-size: 11px; letter-spacing: 0.16em; color: #6B85A6; }

@media (min-width: 880px) {
  .menu { display: none; }
}

/* ============================================
   section 基本パターン
   ============================================ */
.section { position: relative; padding-block: clamp(66px,9vw,120px); background: #FFFFFF; overflow: hidden; }
.section--alt { background: #FFF3E6; }
.section--dark { background: #172E4A; color: #EAF0F6; }
.section--tight { padding-block: clamp(40px,6vw,80px); }

.section__head-row { display: flex; flex-wrap: wrap; align-items: center; gap: clamp(22px,4vw,48px); margin-bottom: clamp(34px,5vw,56px); }
.section__head { flex: 1 1 320px; min-width: 0; max-width: 760px; margin-bottom: clamp(32px,5vw,64px); }
.section__head-row .section__head { margin-bottom: 0; }
.section__head--center { margin-inline: auto; text-align: center; }
.section__deco { flex: 0 0 auto; width: clamp(120px,17vw,200px); aspect-ratio: 1/1; }
.section__deco img { width: 100%; height: 100%; object-fit: cover; display: block; border-radius: 32px; }
.section__eyebrow {
  display: inline-block; margin: 0 0 18px; font-weight: 700; font-size: 11px; line-height: 1;
  letter-spacing: 0.22em; color: #FFFFFF; background: #172E4A; padding: 9px 16px; border-radius: 999px;
  transform: rotate(-2deg);
}
.section--dark .section__eyebrow, .section--cta .section__eyebrow { background: #DC8541; color: #172E4A; }
.section__heading { margin: 0; font-weight: 900; font-size: clamp(26px,3.6vw,44px); line-height: 1.42; letter-spacing: -0.01em; color: #172E4A; }
.section--dark .section__heading { color: #FFFFFF; }
.section__lead { margin: 18px 0 0; font-size: 15px; line-height: 2; color: #56637A; }
.section--dark .section__lead { color: #C3D0E0; }

/* ============================================
   hero
   ============================================ */
.hero { padding-top: clamp(48px,8vw,92px); padding-bottom: clamp(60px,9vw,104px); background: linear-gradient(180deg,#FFFFFF 0%,#FFF3E6 100%); overflow: hidden; }
.hero__inner { display: grid; gap: clamp(40px,6vw,64px); align-items: center; }
.hero__eyebrow { display: flex; align-items: center; gap: 14px; font-size: 11.5px; letter-spacing: 0.22em; color: #8A7B6C; margin: 0 0 clamp(20px,3vw,26px); }
.hero__eyebrow-line { width: 7px; height: 7px; border-radius: 50%; background: #DC8541; }
.hero__heading { margin: 0; font-weight: 900; font-size: clamp(26px,4.2vw,52px); line-height: 1.45; letter-spacing: -0.01em; color: #172E4A; }
.hero__line { display: block; }
.hero__highlight { position: relative; z-index: 1; color: #172E4A; }
.hero__line:last-child .hero__highlight { display: inline-block; }
.hero__line:last-child { position: relative; display: inline-block; }
.hero__lead { margin: clamp(24px,3vw,32px) 0 0; font-size: 15px; line-height: 2.05; color: #56637A; max-width: 46ch; }
.hero__tags { margin-top: clamp(22px,3vw,30px); }
.hero__actions { margin-top: clamp(28px,4vw,38px); }

.hero__visual { position: relative; display: flex; justify-content: center; }
.hero__photo {
  position: relative; width: 100%; max-width: 320px; margin: 0 auto; aspect-ratio: 4/5;
  border: 2.5px solid #172E4A; border-radius: 170px 170px 26px 26px;
  background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px);
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
.hero__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #8A93A3; background: #FFFFFF; padding: 6px 14px; border: 1px solid #E3E6EB; border-radius: 999px; }

@media (min-width: 860px) {
  .hero__inner { grid-template-columns: minmax(0,1fr) 320px; }
  .hero__visual { order: 2; }
}

/* ============================================
   tile-grid（PROBLEMS / TEAM / WORK STYLE 共通／太枠＋オフセット影のポップカード）
   ============================================ */
.tile-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 16px; }
.tile { display: flex; flex-direction: column; align-items: center; gap: 18px; text-align: center; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 24px; padding: clamp(24px,3vw,32px); box-shadow: 6px 6px 0 #172E4A; }
.tile__icon img { width: auto; height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
.tile__text { margin: 0; font-size: 14.5px; line-height: 1.85; color: #172E4A; font-weight: 500; }
.tile__label { font-size: 14px; font-weight: 700; line-height: 1.6; color: #172E4A; }

.tile-grid--dot .tile--row { flex-direction: row; align-items: center; justify-content: flex-start; gap: 14px; text-align: left; box-shadow: none; padding: 20px 22px; }
.tile__dot { flex: none; width: 28px; height: 28px; border-radius: 50%; background: rgba(220,133,65,0.14); display: flex; align-items: center; justify-content: center; }
.tile__dot::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: #DC8541; }

@media (min-width: 640px) {
  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
}
@media (min-width: 880px) {
  .tile-grid--6 { grid-template-columns: repeat(6,1fr); }
  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
}

/* ============================================
   timeline（SCOPE / PROFILE経歴 共通／カード積み上げ型のチェックリスト）
   ============================================ */
.timeline { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.timeline__item { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 16px; padding: 16px 20px; border: 3px dashed #172E4A; border-radius: 18px; background: #FFFFFF; }
.timeline__no { font-size: 12px; letter-spacing: 0.14em; color: #A7AFBC; flex: none; width: 22px; }
.timeline__label { flex: 1; font-size: 15px; font-weight: 500; color: #172E4A; min-width: 120px; }
.timeline__badge { flex: none; font-size: 11px; letter-spacing: 0.04em; color: #8A93A3; }
.timeline__item--covered { border: 3px solid #172E4A; border-left-width: 10px; border-left-color: #DC8541; }
.timeline__item--covered .timeline__no { color: #DC8541; }
.timeline__item--covered .timeline__badge { color: #C06E2E; font-weight: 600; background: rgba(220,133,65,0.12); border-radius: 999px; padding: 6px 12px; }
.timeline__item--highlight { border: 3px solid #172E4A; background: #A85A1E; }
.timeline__item--highlight .timeline__no,
.timeline__item--highlight .timeline__label,
.timeline__item--highlight .timeline__badge { color: #FFFFFF; }

.timeline--profile .timeline__item { border: 3px solid #172E4A; border-style: solid; display: flex; align-items: flex-start; gap: 18px; text-align: left; }
.timeline--profile .timeline__label { flex: none; width: 78px; font-size: 13px; font-weight: 600; color: #172E4A; }
.timeline--profile .timeline__badge { flex: 1; min-width: 180px; font-size: 13.5px; line-height: 1.9; letter-spacing: normal; color: #56637A; font-weight: 400; text-align: left; }
.timeline--profile .timeline__item--highlight { background: #A85A1E; }
.timeline--profile .timeline__item--highlight .timeline__label,
.timeline--profile .timeline__item--highlight .timeline__badge { color: #FFFFFF; }

/* ============================================
   philosophy（PHILOSOPHY）
   ============================================ */
.chain { display: grid; gap: 14px; grid-template-columns: repeat(auto-fit,minmax(200px,1fr)); align-items: stretch; max-width: 920px; margin: 0 auto; }
.chain__node { background: #1E3A5C; color: #FFFFFF; border: 3px solid #E0B98F; border-radius: 22px; padding: clamp(22px,3vw,30px); text-align: center; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; }
.chain__node--accent { background: #FFFFFF; color: #172E4A; border: none; box-shadow: 8px 8px 0 #A85A1E; }
.chain__icon img { width: clamp(60px,8vw,92px); height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
.chain__role { margin: 0; font-weight: 600; font-size: 13px; letter-spacing: 0.1em; color: inherit; }
.chain__node--accent .chain__role { color: #C06E2E; }
.chain__points { list-style: none; margin: 16px 0 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
.chain__points .tag { font-size: 11px; padding: 6px 13px; border: 2.5px solid #172E4A; }
.chain__arrow { display: none; align-items: center; justify-content: center; color: #DC8541; font-size: 18px; }

.philosophy__points { list-style: none; margin: 22px 0 0; padding: 0; display: grid; gap: 12px; max-width: 40ch; }
.philosophy__points li { font-size: 14.5px; color: #FFFFFF; padding-left: 22px; position: relative; }
.philosophy__points li::before { content: ""; position: absolute; left: 0; top: 8px; width: 6px; height: 6px; border-radius: 50%; background: #DC8541; }

@media (min-width: 820px) {
  .chain__arrow { display: flex; }
}

/* ============================================
   work-card（WORKS／クリックでモーダル詳細を開くポップカード）
   ============================================ */
.work-grid { display: grid; grid-template-columns: 1fr; gap: 26px; }
.work-card { display: flex; flex-direction: column; cursor: pointer; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 26px; overflow: hidden; box-shadow: 8px 8px 0 #172E4A; transition: transform .2s ease; }
.work-card:hover { transform: translate(-2px,-2px); }
.work-card__media { position: relative; aspect-ratio: 4/3; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); overflow: hidden; }
.work-card__media img { display: block; width: 100%; height: 100%; object-fit: cover; }
.work-card__media--placeholder { display: flex; align-items: center; justify-content: center; }
.work-card__media--placeholder span { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 6px 12px; border: 1px solid #E3E6EB; border-radius: 999px; }
.work-card__body { padding: 26px clamp(20px,3vw,28px) 28px; display: flex; flex-direction: column; gap: 18px; }
.work-card__no { margin: 0; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
.work-card__title { margin: 10px 0 0; font-weight: 700; font-size: 20px; line-height: 1.5; color: #172E4A; }
.work-card__field-label { margin: 0 0 8px; font-size: 10px; letter-spacing: 0.18em; color: #A7AFBC; text-transform: uppercase; }
.work-card__roles { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.work-card__role { font-size: 12px; color: #3E4A5C; border: 2.5px solid #172E4A; border-radius: 999px; padding: 5px 12px; white-space: nowrap; }
.work-card__text { margin: 0; font-size: 13px; line-height: 1.95; color: #56637A; }
.work-card__result { margin: 0; padding: 14px 18px; background: rgba(220,133,65,0.1); border-left: 10px solid #DC8541; border-radius: 14px; font-size: 13px; font-weight: 700; color: #A85A1E; line-height: 1.75; }
.work-card__more { margin: 0; display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; letter-spacing: 0.08em; color: #A85A1E; }

@media (min-width: 720px) {
  .work-grid { grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); }
}

/* ============================================
   process-row（DIRECTION SAMPLE／番号バッジ入りカードのグリッド）
   ============================================ */
.process-row { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); gap: 12px; }
.process-row__item { display: flex; align-items: center; gap: 16px; padding: 20px 22px; border-radius: 20px; background: #FFFFFF; border: 3px solid #172E4A; }
.process-row__no { flex: none; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; background: rgba(220,133,65,0.12); color: #C06E2E; }
.process-row__label { font-size: 14.5px; line-height: 1.7; font-weight: 500; color: #172E4A; }
.process-row__item--highlight { background: #A85A1E; }
.process-row__item--highlight .process-row__no { background: rgba(255,255,255,0.22); color: #FFFFFF; }
.process-row__item--highlight .process-row__label { color: #FFFFFF; }

/* ============================================
   profile（PROFILE）
   ============================================ */
.profile__top { display: flex; flex-direction: column; align-items: center; gap: 22px; text-align: center; margin-bottom: clamp(40px,6vw,64px); }
.profile__photo { width: 160px; height: 200px; border-radius: 90px 90px 20px 20px; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); border: 2.5px solid #172E4A; display: flex; align-items: center; justify-content: center; overflow: hidden; }
.profile__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 10px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 5px 10px; border-radius: 999px; }
.profile__name { margin: 0; font-weight: 900; font-size: clamp(23px,2.8vw,30px); color: #172E4A; }
.profile__name-en { display: block; margin-top: 6px; font-size: 11px; letter-spacing: 0.2em; color: #A7AFBC; }
.profile__role { margin: 12px 0 0; font-size: 13px; color: #56637A; }

.stat-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px 12px; margin-top: clamp(36px,5vw,52px); }
.stat-grid > div { padding-top: 20px; border-top: 3px solid #DC8541; }
.stat__label { margin: 0; font-size: 10px; letter-spacing: 0.14em; color: #A7AFBC; }
.stat__value { margin: 10px 0 0; font-size: 13.5px; line-height: 1.8; color: #172E4A; }

.pull-quote { margin: clamp(36px,5vw,56px) 0 0; text-align: center; font-weight: 900; font-size: clamp(19px,2.6vw,28px); line-height: 1.75; color: #C06E2E; max-width: 32ch; }

/* ============================================
   cta-dark（最終CTA）
   ============================================ */
.section--cta { background: #172E4A; color: #FFFFFF; text-align: center; }
.cta__bubbles { justify-content: center; margin-top: clamp(28px,4vw,40px); }
.cta__bubbles .tag { color: #FFFFFF; border: 2.5px solid #E0B98F; background: rgba(255,255,255,0.06); }
.cta__body { margin: clamp(24px,4vw,34px) auto 0; max-width: 46ch; font-size: 15px; line-height: 2.05; color: #C3D0E0; }
.cta__actions { margin-top: clamp(32px,5vw,46px); display: flex; flex-direction: column; align-items: center; gap: 18px; }
.cta__email { font-size: 14px; letter-spacing: 0.04em; color: #FFFFFF; border-bottom: 1px solid rgba(224,185,143,0.6); padding-bottom: 3px; }
.cta__note { margin: 0; font-size: 11px; letter-spacing: 0.1em; color: #9DB4CD; }

/* ============================================
   contact + form
   ============================================ */
.contact__lead { max-width: 46ch; margin: 0; font-size: 14px; line-height: 2; color: #56637A; }
.contact__frame { display: none; width: 0; height: 0; border: 0; }

.form { max-width: 660px; }
.form.is-sent { display: none; }
.form__eyebrow { margin: 0 0 26px; font-size: 11px; letter-spacing: 0.2em; color: #A7AFBC; }
.form__fields { display: grid; gap: 24px; }
.form__field { display: grid; gap: 8px; }
.form__label { font-size: 13px; font-weight: 500; color: #172E4A; }
.form__required { color: #DC8541; }
.form__input { width: 100%; font: inherit; font-size: 16px; color: #172E4A; background: transparent; border: none; border-bottom: 3px solid #172E4A; padding: 12px 0; outline: none; transition: border-color .3s ease; }
.form__input:focus { border-bottom-color: #DC8541; }
.form__hint { font-size: 12px; color: #8A93A3; line-height: 1.8; }
.form__fieldset { margin: 0; padding: 22px 24px; border: 3px solid #172E4A; border-radius: 20px; display: grid; gap: 14px; background: #FFF3E6; }
.form__legend { font-size: 13px; font-weight: 500; color: #172E4A; padding: 0 8px; margin: 0; }
.form__radio-label { display: flex; align-items: center; gap: 12px; font-size: 15px; color: #3E4A5C; cursor: pointer; }
.form__radio { accent-color: #DC8541; width: 18px; height: 18px; }
.form__other-input { width: 100%; font: inherit; font-size: 16px; color: #172E4A; background: transparent; border: none; border-bottom: 3px solid #172E4A; padding: 10px 0; outline: none; margin-left: 30px; max-width: calc(100% - 30px); display: none; }
.form__fieldset.is-other .form__other-input { display: block; }
.form__textarea { width: 100%; font: inherit; font-size: 16px; color: #172E4A; background: #FFF3E6; border: 3px solid #172E4A; border-radius: 16px; padding: 16px; outline: none; resize: vertical; transition: border-color .3s ease; }
.form__textarea:focus { border-color: #DC8541; }
.form__checkbox-label { display: flex; align-items: flex-start; gap: 12px; font-size: 14px; color: #3E4A5C; line-height: 1.9; cursor: pointer; }
.form__checkbox { accent-color: #DC8541; width: 18px; height: 18px; margin-top: 3px; }
.form__privacy-link { border-bottom: 1px solid rgba(23,46,74,0.28); }
.form__submit { margin-top: 8px; justify-self: start; display: inline-flex; align-items: center; gap: 14px; background: #DC8541; color: #FFFFFF; font-weight: 700; font-size: 15px; letter-spacing: 0.09em; padding: 21px 40px; border: none; border-radius: 999px; cursor: pointer; box-shadow: 5px 5px 0 #172E4A; transition: background .25s ease, transform .15s ease; }
.form__submit:hover { background: #C06E2E; transform: translateY(-1px); }

.thanks { max-width: 660px; display: none; }
.thanks.is-sent { display: block; }
.thanks__eyebrow { margin: 0; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
.thanks__title { margin: 18px 0 0; font-weight: 700; font-size: 19px; color: #172E4A; }
.thanks__message { margin: 12px 0 0; font-size: 14px; line-height: 2; color: #56637A; }

/* ============================================
   case-detail モーダル（WORKSカードのクリックで開く）
   ============================================ */
.modal-overlay {
  position: fixed; inset: 0; z-index: 120; background: rgba(23,46,74,0.62);
  display: flex; align-items: center; justify-content: center; padding: clamp(16px,4vw,48px);
  overflow-y: auto; opacity: 0; visibility: hidden; pointer-events: none; transition: opacity .3s ease, visibility .3s ease;
}
.modal-overlay.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
.modal { position: relative; width: 100%; max-width: 640px; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 28px; box-shadow: 10px 10px 0 #A85A1E; padding: clamp(26px,4vw,40px); margin: auto; }
.modal__close { position: absolute; top: 14px; right: 14px; width: 44px; height: 44px; border-radius: 50%; border: 3px solid #172E4A; background: #FFFFFF; color: #172E4A; font-weight: 700; font-size: 18px; line-height: 1; cursor: pointer; }
.modal__no { margin: 0; display: inline-block; font-weight: 700; font-size: 11px; letter-spacing: 0.22em; color: #FFFFFF; background: #172E4A; padding: 9px 16px; border-radius: 999px; transform: rotate(-2deg); }
.modal__title { margin: 18px 0 0; font-weight: 900; font-size: clamp(21px,2.8vw,28px); line-height: 1.45; color: #172E4A; }
.modal__block { margin-top: 26px; }
.modal__field-label { margin: 0 0 10px; font-weight: 700; font-size: 10px; letter-spacing: 0.18em; color: #A7AFBC; }
.modal__role { font-size: 12px; font-weight: 700; color: #172E4A; border: 2.5px solid #172E4A; border-radius: 999px; padding: 6px 13px; }
.modal__text { margin: 0; font-size: 14.5px; line-height: 1.95; color: #3E4A5C; }
.modal__result { margin: 24px 0 0; padding: 16px 20px; background: rgba(220,133,65,0.1); border-left: 10px solid #DC8541; border-radius: 14px; font-size: 14px; font-weight: 700; color: #A85A1E; line-height: 1.8; }
.modal__cta { margin-top: 28px; }

/* ============================================
   site-footer（TOPページフッター）
   ============================================ */
.site-footer { background: #172E4A; color: #FFFFFF; padding: clamp(44px,5vw,64px) clamp(20px,5vw,56px) clamp(26px,3vw,34px); margin-top: auto; }
.site-footer__grid { max-width: 1180px; margin: 0 auto; display: flex; flex-wrap: wrap; gap: clamp(24px,4vw,48px); align-items: flex-start; justify-content: space-between; }
.site-footer__name { margin: 0; font-size: 18px; letter-spacing: 0.06em; }
.site-footer__role { margin: 10px 0 0; font-size: 12px; color: #9DB4CD; }
.site-footer__social { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 20px; font-size: 12px; letter-spacing: 0.06em; }
.site-footer__social-link { display: inline-flex; align-items: center; gap: 9px; color: #C3D0E0; }
.site-footer__copyright { max-width: 1180px; margin: clamp(28px,4vw,42px) auto 0; font-size: 11px; letter-spacing: 0.12em; color: #6B85A6; }

