// Scan every visible text element for color-vs-background contrast issues
function getBgColor(el) {
  let node = el;
  while (node) {
    const bg = getComputedStyle(node).backgroundColor;
    if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') return bg;
    node = node.parentElement;
  }
  return 'rgb(255,255,255)';
}
function luminance(rgb) {
  const m = rgb.match(/[\d.]+/g).map(Number);
  const [r,g,b] = m;
  return 0.2126*r + 0.7152*g + 0.0722*b;
}
const results = [];
document.querySelectorAll('.top-shell *').forEach(el => {
  if (el.children.length > 0) return; // leaf nodes only
  const text = el.textContent.trim();
  if (!text) return;
  const cs = getComputedStyle(el);
  if (cs.display === 'none' || cs.visibility === 'hidden' || parseFloat(cs.opacity) === 0) return;
  const color = cs.color;
  const bg = getBgColor(el);
  const diff = Math.abs(luminance(color) - luminance(bg));
  if (diff < 40) {
    results.push({text: text.slice(0,30), color, bg, diff: Math.round(diff), tag: el.tagName, cls: el.className});
  }
});
JSON.stringify(results, null, 1)

