function parseColor(str) {
  const m = str.match(/[\d.]+/g).map(Number);
  return {r: m[0], g: m[1], b: m[2], a: m.length > 3 ? m[3] : 1};
}
function compositeOverWhite(rgba) {
  const {r,g,b,a} = rgba;
  return { r: r*a + 255*(1-a), g: g*a + 255*(1-a), b: b*a + 255*(1-a) };
}
function getBgChain(el) {
  // walk up and composite all backgrounds over white
  const chain = [];
  let node = el;
  while (node) {
    const bg = getComputedStyle(node).backgroundColor;
    chain.unshift(bg);
    node = node.parentElement;
  }
  let result = {r:255,g:255,b:255};
  chain.forEach(c => {
    const p = parseColor(c);
    if (p.a === 0) return;
    result = { r: p.r*p.a + result.r*(1-p.a), g: p.g*p.a + result.g*(1-p.a), b: p.b*p.a + result.b*(1-p.a) };
  });
  return result;
}
function luminance(c) { return 0.2126*c.r + 0.7152*c.g + 0.0722*c.b; }
const results = [];
const seen = new Set();
document.querySelectorAll('.top-shell *').forEach(el => {
  if (el.children.length > 0) return;
  const text = el.textContent.trim();
  if (!text) return;
  const cs = getComputedStyle(el);
  if (cs.display === 'none' || cs.visibility === 'hidden' || parseFloat(cs.opacity) === 0) return;
  const colorP = parseColor(cs.color);
  const bg = getBgChain(el);
  const diff = Math.abs(luminance(colorP) - luminance(bg));
  const key = el.className + '|' + text.slice(0,20);
  if (diff < 60 && !seen.has(key)) {
    seen.add(key);
    results.push({text: text.slice(0,30), color: cs.color, bg: JSON.stringify(bg), diff: Math.round(diff), cls: el.className});
  }
});
JSON.stringify(results, null, 1)

